<?php require_once __DIR__.'/../../includes/bootstrap.php'; if(current_user()) redirect('user/dashboard/index.php'); $pageTitle='Sign in'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');$s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u && password_verify($_POST['password']??'',$u['password_hash'])){if($u['account_status']!=='approved'){ $error='Your account is currently '.str_replace('_',' ',$u['account_status']).'.'; } else {login_user((int)$u['id']);db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);audit('login','user',(int)$u['id']);$roleStmt=db()->prepare("SELECT GROUP_CONCAT(r.name) FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=?");$roleStmt->execute([$u['id']]);$roles=(string)$roleStmt->fetchColumn();$isStaff=(bool)array_intersect(['Administrator','Management','Event','HR','Author','IT'],array_filter(array_map('trim',explode(',',$roles))));redirect($isStaff?'admin/dashboard/index.php':'user/dashboard/index.php');}}else{$error='Invalid email or password.';}} require __DIR__.'/../../includes/header.php'; ?><section class="auth-shell"><div class="auth-card"><div class="eyebrow">Welcome back</div><h1>Sign in</h1><p>Access your bookings, notifications and event planning workspace.</p><?php if($error): ?><div class="badge badge-red" style="margin-bottom:15px"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field" style="margin-top:15px"><label>Password</label><input type="password" name="password" required></div><button class="btn btn-primary" style="width:100%;margin-top:20px">Sign in</button></form><p style="text-align:right;margin:12px 0 0"><a style="color:var(--forest);font-weight:700" href="<?=url('public/auth/forgot_password.php')?>">Forgot password?</a></p><p class="kicker" style="margin-top:20px">No account? <a style="color:var(--forest);font-weight:700" href="<?=url('public/auth/register.php')?>">Request access</a></p></div></section><?php require __DIR__.'/../../includes/footer.php'; ?>
